import pandas as pd
import numpy as np

# Load the data
df = pd.read_csv('chunks_csv/changespillover/changespillover_no2crime_no2_Q3_2021_to_Q4_2021.csv')
adjacency_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Calculate the change in NO2 between Q3 2021 and Q4 2021
df['change'] = df['Q4_2021_value'] - df['Q3_2021_value']

# Create a list of neighbors for each borough
neighbors = {}
for index, row in adjacency_df.iterrows():
    if row['borough'] not in neighbors:
        neighbors[row['borough']] = []
    neighbors[row['borough']].append(row['neighbor'])

# Calculate the average change in NO2 for each borough and its neighbors
average_change = {}
for borough in df['borough'].unique():
    if borough not in average_change:
        average_change[borough] = []
    for neighbor in neighbors.get(borough, []):
        if neighbor in df['borough'].unique():
            average_change[borough].append((df.loc[df['borough'] == neighbor, 'change'].values[0] + df.loc[df['borough'] == borough, 'change'].values[0]) / 2)

# Calculate the correlation between the change in NO2 for each borough and its neighbors
correlation = {}
for borough in df['borough'].unique():
    if borough not in correlation:
        correlation[borough] = []
    for neighbor in neighbors.get(borough, []):
        if neighbor in df['borough'].unique():
            correlation[borough].append(np.corrcoef([df.loc[df['borough'] == borough, 'change'].values[0], df.loc[df['borough'] == neighbor, 'change'].values[0]])[0][1])

# Calculate the test statistic and p-value using a permutation test
test_statistic = 0
p_value = 0
for _ in range(500):
    # Shuffle the changes in NO2 for each borough and its neighbors
    shuffled_changes = {}
    for borough in df['borough'].unique():
        if borough not in shuffled_changes:
            shuffled_changes[borough] = []
        for neighbor in neighbors.get(borough, []):
            if neighbor in df['borough'].unique():
                shuffled_changes[borough].append(np.random.choice([df.loc[df['borough'] == neighbor, 'change'].values[0], df.loc[df['borough'] == borough, 'change'].values[0]]))
    # Calculate the correlation between the shuffled changes in NO2 for each borough and its neighbors
    shuffled_correlation = {}
    for borough in df['borough'].unique():
        if borough not in shuffled_correlation:
            shuffled_correlation[borough] = []
        for neighbor in neighbors.get(borough, []):
            if neighbor in df['borough'].unique():
                shuffled_correlation[borough].append(np.corrcoef([shuffled_changes[borough][0], shuffled_changes[neighbor][0]])[0][1])
    # Calculate the test statistic
    shuffled_test_statistic = 0
    for borough in df['borough'].unique():
        if borough in shuffled_correlation:
            shuffled_test_statistic += np.mean(shuffled_correlation[borough])
    # Update the test statistic and p-value
    test_statistic += np.mean(correlation.values())
    p_value += 1 - np.mean([1 for _ in range(500) if shuffled_test_statistic >= np.mean(correlation.values())])

# Print the final answer
print(f"FINAL ANSWER: {'CLUSTERED' if p_value < 0.05 else 'NOT CLUSTERED'} (test statistic = {test_statistic}, p = {p_value / 500})")
